/// Starts a SHA-1 computation: makes the streaming state `*state` represent the empty message.
///
/// Contract: `VG.Spec.Sha1.initContract`. The streaming state is the hash value followed by a buffered partial block (`VG.Spec.Sha1.Repr`).
///
/// # Safety
///
/// * `state` must be valid for reads and writes of 84 bytes.
/// * `state` must not wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub(crate) unsafe extern "C" fn vg_sha1_init(state: *mut [u8; 84]) {
    core::arch::naked_asm!(
        "movw r12, #8961",
        "movt r12, #26437",
        "str r12, [r0, #0]",
        "movw r12, #43913",
        "movt r12, #61389",
        "str r12, [r0, #4]",
        "movw r12, #56574",
        "movt r12, #39098",
        "str r12, [r0, #8]",
        "movw r12, #21622",
        "movt r12, #4146",
        "str r12, [r0, #12]",
        "movw r12, #57840",
        "movt r12, #50130",
        "str r12, [r0, #16]",
        "bx lr",
    )
}

